"""Temporary, branch-scoped transport for locally reviewed patches; removes itself."""
import base64
import hashlib
from pathlib import Path
import subprocess
import sys
import zlib

BRANCH = "refactor/frontend-asset-registration"
assert subprocess.check_output(["git", "branch", "--show-current"], text=True).strip() == BRANCH
assert subprocess.check_output(["git", "rev-parse", "HEAD~1"], text=True).strip() == "919c0933a65d096a3300333dc940e10d3394a390"

def apply_patch(encoded, digest, message):
    patch = zlib.decompress(base64.b64decode(encoded))
    assert hashlib.sha256(patch).hexdigest() == digest
    subprocess.run(["git", "apply", "--check", "-"], input=patch, check=True)
    subprocess.run(["git", "apply", "--index", "-"], input=patch, check=True)
    subprocess.run(["git", "commit", "-m", message], check=True)

apply_patch("", "d31f2661e13d1023d054ef4d5641be13c1990171100b4971e58bebb8b9c88baa", "Declare complete Management asset registry and remove runtime extensions")

apply_patch("", "c847f9c6e190079fce440368995bcfb8311e16c156590569b58cdfc0d35946d8", "Cover canonical registry, lazy imports and genuine HA asset serving")

subprocess.run([sys.executable, "-m", "pip", "install", "ruff"], check=True)
changed = subprocess.check_output(["git", "diff", "--name-only", "919c0933a65d096a3300333dc940e10d3394a390", "--", "custom_components"], text=True).splitlines()
subprocess.run(["ruff", "check", *changed], check=True)
subprocess.run(["ruff", "format", *changed], check=True)
if subprocess.check_output(["git", "diff", "--name-only"], text=True).strip():
    subprocess.run(["git", "add", "--", *changed], check=True)
    subprocess.run(["git", "commit", "-m", "Format canonical asset registration changes"], check=True)
subprocess.run(["node", "--test", *map(str, sorted(Path("tests").glob("*.test.mjs")))], check=True)
subprocess.run(["git", "rm", ".asset-registry-patch.py", ".github/workflows/asset-registry-workbench.yml"], check=True)
subprocess.run(["git", "commit", "-m", "Remove temporary asset registry workbench"], check=True)
